import gurobipy as gp
from gurobipy import GRB
records = [r for r in LEGACY_RECORDS if r['source'].endswith('parameters.csv')]
if not records or len(records) != 10:
    raise ValueError('Expected 10 truck records in LEGACY_RECORDS.')
I = [str(int(r['values']['truck_id'])) for r in records]
T = ['1', '2', '3', '4']
Q = {r['values']['truck_id']: float(r['values']['Q']) for r in records}
S = {r['values']['truck_id']: float(r['values']['S']) for r in records}
C = {r['values']['truck_id']: float(r['values']['C']) for r in records}
d = {'1': float(records[0]['values']['d1']), '2': float(records[0]['values']['d2']), '3': float(records[0]['values']['d3']), '4': float(records[0]['values']['d4'])}
T0 = ['0'] + T
T1 = T + ['5']
m = gp.Model('Truck_Scheduling')
x_vars = m.addVars(I, T, lb=0, vtype=GRB.CONTINUOUS, name='')
y_vars = m.addVars(I, T, vtype=GRB.BINARY, name='')
u_vars = m.addVars(I, T, vtype=GRB.BINARY, name='')
z_vars = m.addVars(I, T, vtype=GRB.BINARY, name='')
y0 = {(i, '0'): 0 for i in I}
x0 = {(i, '0'): 0 for i in I}
y5 = {(i, '5'): 0 for i in I}
m.setObjective(gp.quicksum((S[i] * u_vars[i, t] + C[i] * x_vars[i, t] for i in I for t in T)), GRB.MINIMIZE)
for i in I:
    for idx, t in enumerate(T):
        t_prev = str(int(t) - 1)
        y_prev = y0[i, t_prev] if t_prev == '0' else y_vars[i, t_prev]
        m.addConstr(u_vars[i, t] >= y_vars[i, t] - y_prev, name='')
        m.addConstr(u_vars[i, t] <= 1 - y_prev, name='')
        m.addConstr(u_vars[i, t] <= y_vars[i, t], name='')
    m.addConstr(u_vars[i, '4'] == 0, name='')
for i in I:
    for t in ['1', '2', '3']:
        t_next = str(int(t) + 1)
        y_next = y_vars[i, t_next] if t_next in T else y5[i, t_next]
        m.addConstr(z_vars[i, t] >= y_vars[i, t] - y_next, name='')
        m.addConstr(z_vars[i, t] <= y_vars[i, t], name='')
        m.addConstr(z_vars[i, t] <= 1 - y_next, name='')
for i in I:
    for t in ['1', '2', '3']:
        t_next = str(int(t) + 1)
        m.addConstr(y_vars[i, t_next] >= u_vars[i, t], name='')
for i in I:
    for t in ['1', '2']:
        t1 = str(int(t) + 1)
        t2 = str(int(t) + 2)
        m.addConstr(y_vars[i, t1] <= 1 - z_vars[i, t], name='')
        m.addConstr(y_vars[i, t2] <= 1 - z_vars[i, t], name='')
for i in I:
    for t in T:
        m.addConstr(x_vars[i, t] <= Q[i] * y_vars[i, t], name='')
        m.addConstr(x_vars[i, t] >= 0, name='')
for t in T:
    m.addConstr(gp.quicksum((x_vars[i, t] for i in I)) >= d[t], name='')
    m.addConstr(gp.quicksum((x_vars[i, t] for i in I)) <= 0.9 * gp.quicksum((Q[i] * y_vars[i, t] for i in I)), name='')
for i in I:
    for t in ['2', '3', '4']:
        t_prev = str(int(t) - 1)
        x_prev = x0[i, t_prev] if t_prev == '0' else x_vars[i, t_prev]
        m.addConstr(x_vars[i, t] - x_prev <= 300, name='')
        m.addConstr(x_prev - x_vars[i, t] <= 300, name='')
for i in I:
    pass
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')